32	export function resolveLedgerRoot(): string {
33	  const args = process.argv;
34	  const flagIndex = args.indexOf('--ledger-dir');
35	  if (flagIndex !== -1) {
36	    // Next token must exist and must not itself be a flag
37	    if (flagIndex + 1 >= args.length || args[flagIndex + 1]!.startsWith('--')) {
38	      throw new Error(
